<?php
namespace Opencart\Catalog\Model\Extension\Linnworks; class Channel extends \Opencart\System\Engine\Model{public function add(array $r):array{$sid=trim($r['LinnworksUniqueIdentifier']??'');$name=trim($r['AccountName']??'');if(!$sid||!$name)return ['Error'=>'Missing account identity.','AuthorizationToken'=>null];$token=bin2hex(random_bytes(32));$hash=password_hash($token,PASSWORD_DEFAULT);$this->db->query("INSERT INTO `".DB_PREFIX."linnworks_account` SET sid_registration='".$this->db->escape($sid)."',account_name='".$this->db->escape($name)."',email='".$this->db->escape($r['Email']??'')."',authorization_token_hash='".$this->db->escape($hash)."',status=1,date_added=NOW(),date_modified=NOW()");return ['Error'=>null,'AuthorizationToken'=>$token];}public function auth(array $r):array{$t=$r['AuthorizationToken']??'';foreach($this->db->query("SELECT * FROM `".DB_PREFIX."linnworks_account` WHERE status=1")->rows as $x)if(password_verify($t,$x['authorization_token_hash']))return $x;return [];}}